-- 2.10 Inscripciones en materias: cada estudiante en las materias de su grado, por período.
--      Los períodos I, II y III ya terminaron (Completada); el IV está en curso (Activa).
INSERT INTO inscripciones_materia (id_estudiante, id_materia, anio_academico, periodo_academico, seccion,
                                   fecha_inscripcion, estado)
SELECT mt.id_estudiante, m.id_materia, mt.anio_academico, p.periodo, 'A', p.fecha_inicio,
       CASE WHEN p.periodo = 'IV' THEN 'Activa' ELSE 'Completada' END
FROM matriculas mt
JOIN materias m ON m.id_grado = mt.id_grado
CROSS JOIN (SELECT 'I' AS periodo, DATE('2026-01-26') AS fecha_inicio
            UNION ALL SELECT 'II', DATE('2026-04-13')
            UNION ALL SELECT 'III', DATE('2026-07-06')
            UNION ALL SELECT 'IV', DATE('2026-09-14')) p
WHERE mt.anio_academico = 2026;


